// Oriented point cloud (x y z nx ny nz) -> signed distance to the local
// tangent planes -> closed solid. The normals decide inside and outside, so
// no morphological closing is needed and thin walls and small holes survive.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Numerics;
using PicoGK;

/// <summary>
/// Signed distance to an oriented point set. Magnitudes come from tangent
/// planes (Hoppe et al. (1992)): the samples near a query are grouped into
/// faces by normal, and each face gives a Gaussian-weighted mean distance to
/// its samples' planes. Where those faces agree on the side, the nearest
/// face's distance is returned. Where they disagree, at sharp corners and
/// next to thin walls, the side is decided by the generalised winding number
/// of the oriented samples (Barill et al. (2018)): about 1 inside, about 0
/// outside, robust to noise, thin walls and scanner gaps.
/// </summary>
public sealed class OrientedPointSdf : IImplicit
{
    readonly Vector3[] m_avecP, m_avecN;   // positions and unit outward normals (mm)
    readonly float[] m_afArea;             // surface area each sample represents (mm2)
    readonly Vector3 m_vecMin;             // grid origin (mm)
    readonly float m_fCell;                // cell edge (mm)
    readonly int m_nX, m_nY, m_nZ;         // grid size in cells
    readonly int[] m_anFirst;              // cell c holds m_anIndex[m_anFirst[c] .. m_anFirst[c + 1])
    readonly int[] m_anIndex;              // point indices sorted by cell
    readonly int[] m_anNearestCell;        // nearest occupied cell (cell-centre distance)
    readonly int[] m_anOccupied;           // cells that hold samples
    readonly Vector3[] m_avecMoment;       // per occupied cell: sum of area x normal (mm2)
    readonly Vector3[] m_avecCentroid;     // per occupied cell: area-weighted centroid (mm)
    readonly float[] m_afFarWinding;       // per cell: winding from cells beyond nNear, NaN until needed
    readonly float m_fSigma;               // plane-averaging width (mm)
    readonly float m_fInvTwoSigma2;        // Gaussian weight 1 / (2 sigma^2)
    const float fAgreeCos = 0.7f;          // about 45 deg: samples of the same face
    const int nMaxFaces = 6;               // faces considered at one corner
    const int nNear = 2;                   // exact winding sum over this many cells around a query

    public OrientedPointSdf(Vector3[] avecP, Vector3[] avecN, float fCellMM, float fSigmaMM)
    {
        if (avecP.Length == 0 || avecP.Length != avecN.Length) throw new ArgumentException("Need matching points and normals");
        m_avecP = avecP; m_avecN = avecN; m_fCell = fCellMM;
        m_fSigma = fSigmaMM;
        m_fInvTwoSigma2 = 1f / (2f * fSigmaMM * fSigmaMM);

        // Grid over the points with two empty cells of margin on every side.
        Vector3 vecLo = avecP[0], vecHi = avecP[0];
        foreach (Vector3 v in avecP) { vecLo = Vector3.Min(vecLo, v); vecHi = Vector3.Max(vecHi, v); }
        m_vecMin = vecLo - new Vector3(2f * fCellMM);
        Vector3 vecSize = vecHi - m_vecMin + new Vector3(2f * fCellMM);
        m_nX = (int)MathF.Ceiling(vecSize.X / fCellMM) + 1;
        m_nY = (int)MathF.Ceiling(vecSize.Y / fCellMM) + 1;
        m_nZ = (int)MathF.Ceiling(vecSize.Z / fCellMM) + 1;
        int nCells = checked(m_nX * m_nY * m_nZ);

        // Counting sort of the points into cells (compressed-row layout).
        m_anFirst = new int[nCells + 1];
        int[] anCell = new int[avecP.Length];
        for (int i = 0; i < avecP.Length; i++) { anCell[i] = nCellOf(avecP[i]); m_anFirst[anCell[i] + 1]++; }
        for (int c = 0; c < nCells; c++) m_anFirst[c + 1] += m_anFirst[c];
        m_anIndex = new int[avecP.Length];
        int[] anFill = (int[])m_anFirst.Clone();
        for (int i = 0; i < avecP.Length; i++) m_anIndex[anFill[anCell[i]]++] = i;

        // Area per sample from the local density: a disc of one cell radius
        // shared by the samples in it that face the same way.
        m_afArea = new float[avecP.Length];
        for (int i = 0; i < avecP.Length; i++)
        {
            int nSame = 0;
            foreach (int k in anBlock(anCell[i], 1))
                if (Vector3.DistanceSquared(avecP[i], avecP[k]) <= fCellMM * fCellMM &&
                    Vector3.Dot(avecN[i], avecN[k]) > fAgreeCos) nSame++;    // counts i itself
            m_afArea[i] = MathF.PI * fCellMM * fCellMM / nSame;
        }

        // Nearest occupied cell for every cell: breadth-first relaxation over
        // the 26-neighbourhood that keeps the seed with the smaller Euclidean
        // centre distance. Plain breadth-first depth breaks ties arbitrarily.
        m_anNearestCell = new int[nCells];
        Array.Fill(m_anNearestCell, -1);
        int[] anDist2 = new int[nCells];
        Array.Fill(anDist2, int.MaxValue);
        Queue<int> queue = new();
        for (int c = 0; c < nCells; c++)
            if (m_anFirst[c + 1] > m_anFirst[c]) { m_anNearestCell[c] = c; anDist2[c] = 0; queue.Enqueue(c); }
        while (queue.Count > 0)
        {
            int c = queue.Dequeue(), s = m_anNearestCell[c];
            var (sx, sy, sz) = Coords(s);
            var (cx, cy, cz) = Coords(c);
            for (int z = Math.Max(cz - 1, 0); z <= Math.Min(cz + 1, m_nZ - 1); z++)
                for (int y = Math.Max(cy - 1, 0); y <= Math.Min(cy + 1, m_nY - 1); y++)
                    for (int x = Math.Max(cx - 1, 0); x <= Math.Min(cx + 1, m_nX - 1); x++)
                    {
                        int n = x + m_nX * (y + m_nY * z);
                        int nD2 = (x - sx) * (x - sx) + (y - sy) * (y - sy) + (z - sz) * (z - sz);
                        if (nD2 >= anDist2[n]) continue;
                        anDist2[n] = nD2;
                        m_anNearestCell[n] = s;
                        queue.Enqueue(n);
                    }
        }

        // Each occupied cell as one dipole for the far part of the winding number.
        List<int> anOccupied = new();
        for (int c = 0; c < nCells; c++) if (m_anFirst[c + 1] > m_anFirst[c]) anOccupied.Add(c);
        m_anOccupied = anOccupied.ToArray();
        m_avecMoment = new Vector3[m_anOccupied.Length];
        m_avecCentroid = new Vector3[m_anOccupied.Length];
        for (int o = 0; o < m_anOccupied.Length; o++)
        {
            float fA = 0;
            for (int j = m_anFirst[m_anOccupied[o]]; j < m_anFirst[m_anOccupied[o] + 1]; j++)
            {
                int k = m_anIndex[j];
                m_avecMoment[o] += m_afArea[k] * avecN[k];
                m_avecCentroid[o] += m_afArea[k] * avecP[k];
                fA += m_afArea[k];
            }
            m_avecCentroid[o] /= fA;
        }
        m_afFarWinding = new float[nCells];
        Array.Fill(m_afFarWinding, float.NaN);
    }

    (int X, int Y, int Z) Coords(int c) => (c % m_nX, c / m_nX % m_nY, c / (m_nX * m_nY));

    // Winding-number contribution of a dipole (area-weighted normal) at a point.
    static float fDipole(Vector3 vecMoment, Vector3 vecAt, Vector3 vecQuery)
    {
        Vector3 vecD = vecAt - vecQuery;
        float fR2 = vecD.LengthSquared() + 0.0225f;   // 0.15 mm core avoids the 1/r^2 spike
        return Vector3.Dot(vecMoment, vecD) / (4f * MathF.PI * fR2 * MathF.Sqrt(fR2));
    }

    /// <summary>
    /// Winding number at v in cell c: the samples within nNear cells exactly,
    /// the other cells as dipoles evaluated once at the cell centre. Only
    /// queries where faces disagree need it, so the far part is computed on
    /// first use. Two threads may compute the same cell; both store the same value.
    /// </summary>
    float fWinding(Vector3 v, int c)
    {
        var (cx, cy, cz) = Coords(c);
        float fW = m_afFarWinding[c];
        if (float.IsNaN(fW))
        {
            Vector3 vecCentre = m_vecMin + (new Vector3(cx, cy, cz) + new Vector3(0.5f)) * m_fCell;
            fW = 0;
            for (int o = 0; o < m_anOccupied.Length; o++)
            {
                var (x, y, z) = Coords(m_anOccupied[o]);
                if (Math.Max(Math.Abs(x - cx), Math.Max(Math.Abs(y - cy), Math.Abs(z - cz))) > nNear)
                    fW += fDipole(m_avecMoment[o], m_avecCentroid[o], vecCentre);
            }
            m_afFarWinding[c] = fW;
        }
        foreach (int k in anBlock(c, nNear)) fW += fDipole(m_afArea[k] * m_avecN[k], m_avecP[k], v);
        return fW;
    }

    // Cell index of a position, clamped to the grid.
    int nCellOf(Vector3 v)
    {
        Vector3 vecG = (v - m_vecMin) / m_fCell;
        int x = Math.Clamp((int)MathF.Floor(vecG.X), 0, m_nX - 1);
        int y = Math.Clamp((int)MathF.Floor(vecG.Y), 0, m_nY - 1);
        int z = Math.Clamp((int)MathF.Floor(vecG.Z), 0, m_nZ - 1);
        return x + m_nX * (y + m_nY * z);
    }

    [ThreadStatic] static List<int> t_anBlock;   // per-thread scratch list

    /// <summary>
    /// Indices of the samples in the cube of cells within r of cell c. It
    /// holds every sample closer than r cell edges to any point in cell c.
    /// The list is reused by the next call on the same thread.
    /// </summary>
    List<int> anBlock(int c, int r)
    {
        List<int> an = t_anBlock ??= new List<int>(1024);
        an.Clear();
        var (cx, cy, cz) = Coords(c);
        int x0 = Math.Max(cx - r, 0), x1 = Math.Min(cx + r, m_nX - 1);
        for (int z = Math.Max(cz - r, 0); z <= Math.Min(cz + r, m_nZ - 1); z++)
            for (int y = Math.Max(cy - r, 0); y <= Math.Min(cy + r, m_nY - 1); y++)
            {
                // Cells along x are adjacent in memory: one index range per row.
                int nRow = m_nX * (y + m_nY * z);
                for (int j = m_anFirst[nRow + x0]; j < m_anFirst[nRow + x1 + 1]; j++) an.Add(m_anIndex[j]);
            }
        return an;
    }

    /// <summary>
    /// True if point i looks like a surface sample: at least nMin neighbours
    /// within fRadius (at most one cell) face roughly its way, their mean
    /// normal agrees closely with its own, and it lies on their mean tangent
    /// plane within fMaxOffset. Clutter fails the count; a stray point near
    /// the surface fails the normal or the offset test.
    /// </summary>
    public bool bIsSurfacePoint(int i, float fRadius, int nMin, float fMaxOffset)
    {
        Vector3 v = m_avecP[i], vecMean = Vector3.Zero;
        float fOffset = 0;
        int nFound = 0;
        foreach (int k in anBlock(nCellOf(v), 1))
        {
            if (k == i || Vector3.DistanceSquared(v, m_avecP[k]) > fRadius * fRadius ||
                Vector3.Dot(m_avecN[i], m_avecN[k]) <= fAgreeCos) continue;
            vecMean += m_avecN[k];
            fOffset += Vector3.Dot(m_avecN[k], v - m_avecP[k]);   // height above k's plane
            nFound++;
        }
        return nFound >= nMin && Vector3.Dot(m_avecN[i], Vector3.Normalize(vecMean)) > 0.9f &&
               MathF.Abs(fOffset / nFound) <= fMaxOffset;
    }

    /// <summary>
    /// Plane distance of each face among the samples in the list that lie
    /// within the nearest distance plus 2 sigma of v. Face 0 holds the
    /// nearest sample; fReach returns that search radius. Returns the number
    /// of faces found (0 for an empty list).
    /// </summary>
    int nFaces(List<int> an, Vector3 v, Span<float> afDist, out float fReach)
    {
        float fMin2 = float.MaxValue;
        int iNear = -1;
        fReach = float.MaxValue;
        foreach (int k in an)
        {
            float fD2 = Vector3.DistanceSquared(v, m_avecP[k]);
            if (fD2 < fMin2) { fMin2 = fD2; iNear = k; }
        }
        if (iNear < 0) return 0;
        fReach = MathF.Sqrt(fMin2) + 2f * m_fSigma;
        Span<int> anSeed = stackalloc int[nMaxFaces];
        Span<float> afWeight = stackalloc float[nMaxFaces];
        anSeed[0] = iNear; afDist[0] = 0; afWeight[0] = 0;
        int nFound = 1;
        foreach (int k in an)
        {
            Vector3 vecD = v - m_avecP[k];
            float fD2 = vecD.LengthSquared();
            if (fD2 > fReach * fReach) continue;
            int g = 0;
            while (g < nFound && Vector3.Dot(m_avecN[k], m_avecN[anSeed[g]]) <= fAgreeCos) g++;
            if (g == nFound)
            {
                if (nFound == nMaxFaces) continue;
                anSeed[g] = k; afDist[g] = 0; afWeight[g] = 0;
                nFound++;
            }
            // Relative to the nearest distance, so weights stay finite far away.
            float fW = MathF.Max(MathF.Exp(-(fD2 - fMin2) * m_fInvTwoSigma2), 1e-30f);
            afDist[g] += fW * Vector3.Dot(m_avecN[k], vecD);
            afWeight[g] += fW;
        }
        for (int g = 0; g < nFound; g++) afDist[g] /= afWeight[g];
        return nFound;
    }

    // Called from several threads during voxelisation: it only reads fields
    // and its own thread's scratch list.
    public float fSignedDistance(in Vector3 vec)
    {
        // The mesher interpolates vertices along voxel edges. A value within a
        // hair of zero at a voxel node stacks several vertices on that node and
        // leaves needle triangles, so keep values at least 0.003 mm from zero
        // (1 % of a voxel; the surface moves by no more than that).
        float f = fField(vec);
        return MathF.Abs(f) >= 0.003f ? f : (f < 0 ? -0.003f : 0.003f);
    }

    float fField(Vector3 vec)
    {
        int c = nCellOf(vec);
        Span<float> afDist = stackalloc float[nMaxFaces];
        // A block of r cells holds every sample within r cell edges of the
        // query, so the faces are complete once the search radius fits.
        int n = nFaces(anBlock(c, 1), vec, afDist, out float fReach);
        if (fReach > m_fCell) n = nFaces(anBlock(c, nNear), vec, afDist, out fReach);
        if (fReach > nNear * m_fCell)
        {
            // Far from the cloud or inside a scanner gap: use the faces around
            // the nearest occupied cell. Their planes extend across a gap, and
            // out here only the side has to be right.
            n = nFaces(anBlock(m_anNearestCell[c], nNear), vec, afDist, out _);
        }
        bool bAgree = true;
        for (int g = 1; g < n; g++) bAgree &= afDist[g] < 0 == afDist[0] < 0;
        if (bAgree) return afDist[0];
        // Faces disagree: corner or thin wall. Side from the winding number,
        // distance from the closest plane.
        float fMin = float.MaxValue;
        for (int g = 0; g < n; g++) fMin = MathF.Min(fMin, MathF.Abs(afDist[g]));
        return fWinding(vec, c) > 0.5f ? -fMin : fMin;
    }
}

public static class OrientedScanToSolid
{
    // Reconstruction parameters, in millimetres.
    const float fCellMM       = 1.0f;   // bucket size; also the outlier search radius
    const float fSigmaMM      = 0.4f;   // plane-averaging width, below the thinnest wall
    const int   nMinSupport   = 5;      // agreeing neighbours a real surface point has
    const float fMaxOffsetMM  = 0.25f;  // about 4 sigma of the stated range noise
    const float fMaxRejected  = 0.05f;  // more rejects than this means bad normals

    public static void Main(string[] args)
    {
        // Usage: OrientedScanToSolid <scan_normals.xyz> <output folder>
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    /// <summary>
    /// Reads "x y z nx ny nz" rows (space, tab or comma separated). Comments,
    /// headers and rows with fewer than six finite numbers are skipped, and
    /// normals are rescaled to unit length. Culture-invariant parsing.
    /// </summary>
    static (List<Vector3> P, List<Vector3> N, int Skipped) ReadOriented(string strPath)
    {
        List<Vector3> avecP = new(), avecN = new();
        int nSkipped = 0;
        float[] af = new float[6];
        foreach (string strLine in File.ReadLines(strPath))
        {
            string s = strLine.Trim();
            if (s.Length == 0 || s[0] == '#') continue;
            string[] astr = s.Split(new[] { ' ', '\t', ',' }, StringSplitOptions.RemoveEmptyEntries);
            bool bOk = astr.Length >= 6;
            for (int k = 0; bOk && k < 6; k++)
                bOk = float.TryParse(astr[k], NumberStyles.Float, CultureInfo.InvariantCulture, out af[k]) && float.IsFinite(af[k]);
            Vector3 vecN = bOk ? new Vector3(af[3], af[4], af[5]) : Vector3.Zero;
            // A zero or tiny normal carries no orientation; drop the row.
            if (!bOk || vecN.Length() < 0.5f) { nSkipped++; continue; }
            avecP.Add(new Vector3(af[0], af[1], af[2]));
            avecN.Add(Vector3.Normalize(vecN));
        }
        return (avecP, avecN, nSkipped);
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        // 1. Read the oriented cloud.
        var (avecRawP, avecRawN, nSkipped) = ReadOriented(strInputPath);
        if (avecRawP.Count < 1000) throw new InvalidDataException($"Only {avecRawP.Count} valid oriented points");

        // 2. Outlier rejection: a surface point has several neighbours within
        //    one cell that face its way and whose tangent planes it lies on.
        //    Floating clutter has no such neighbours. A stray point near the
        //    surface sits off their planes or faces another way; kept, it
        //    would become the nearest sample and flip the sign around it.
        OrientedPointSdf oAll = new(avecRawP.ToArray(), avecRawN.ToArray(), fCellMM, fSigmaMM);
        List<Vector3> avecP = new(), avecN = new();
        for (int i = 0; i < avecRawP.Count; i++)
            if (oAll.bIsSurfacePoint(i, fCellMM, nMinSupport, fMaxOffsetMM)) { avecP.Add(avecRawP[i]); avecN.Add(avecRawN[i]); }
        float fRejected = 1f - (float)avecP.Count / avecRawP.Count;
        // Clutter is a fraction of a percent. Many rejects mean neighbouring
        // normals disagree, i.e. the file is not consistently oriented.
        if (fRejected > fMaxRejected)
            throw new InvalidDataException($"{fRejected:P1} of the points have no agreeing neighbours; orient the normals consistently first");

        // 3. Global orientation. For a closed surface sampled evenly, the mean
        //    of n.(p - c) is 3 V / A > 0 when the normals point outward. Some
        //    exporters write inward normals; flip them all in that case.
        Vector3 vecCentre = Vector3.Zero;
        foreach (Vector3 v in avecP) vecCentre += v / avecP.Count;
        double dFlux = 0, dRadius = 0;
        for (int i = 0; i < avecP.Count; i++)
        {
            dFlux += Vector3.Dot(avecN[i], avecP[i] - vecCentre);
            dRadius += Vector3.Distance(avecP[i], vecCentre);
        }
        dFlux /= avecP.Count; dRadius /= avecP.Count;
        // Near zero, the orientation is mixed rather than uniformly inverted.
        if (Math.Abs(dFlux) < 0.05 * dRadius)
            throw new InvalidDataException("Normals show no consistent outward or inward orientation");
        bool bFlipped = dFlux < 0;
        if (bFlipped)
            for (int i = 0; i < avecN.Count; i++) avecN[i] = -avecN[i];

        // 4. Build the field on the cleaned points and render it in a box
        //    slightly larger than the cloud. The far-field sign closes small
        //    scanner gaps with the neighbouring tangent planes.
        OrientedPointSdf oField = new(avecP.ToArray(), avecN.ToArray(), fCellMM, fSigmaMM);
        Vector3 vecLo = avecP[0], vecHi = avecP[0];
        foreach (Vector3 v in avecP) { vecLo = Vector3.Min(vecLo, v); vecHi = Vector3.Max(vecHi, v); }
        BBox3 oBox = new(vecLo - new Vector3(2f), vecHi + new Vector3(2f));
        using Voxels voxSolid = new(lib, oField, oBox);
        if (voxSolid.bIsEmpty()) throw new InvalidDataException("Reconstruction is empty; check units and normals");

        // 5. Export in millimetres and report what was built.
        Directory.CreateDirectory(strOutputDir);
        using Mesh mshOut = voxSolid.mshAsMesh();
        mshOut.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);
        voxSolid.CalculateProperties(out float fVolumeMM3, out BBox3 oSolidBox);
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "{0} rows skipped, {1} points, {2:P2} rejected, normals {3}, volume {4:F0} mm3, size {5}",
            nSkipped, avecRawP.Count, fRejected, bFlipped ? "flipped" : "kept", fVolumeMM3, oSolidBox.vecSize()));
    }
}

// Two DfAM fixes on a bracket for PBF-LB/M: a self-supporting gusset under a
// horizontal lip, and a rib thickened to the minimum printable wall.
// Pipeline: closed STL -> voxels -> probe the stated layout -> add gusset and
// rib -> check wall and overhang -> STL.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Numerics;
using PicoGK;

/// <summary>
/// Wedge under a lip, extruded along y. Its back face sits in the web, its top
/// in the lip, and its underside rises from the web to the lip tip at
/// fSlopeDeg from the build plate. The solid is an intersection of
/// half-spaces, so the maximum of their signed distances is exact on the faces
/// and a lower bound near the edges, which is all voxelisation needs.
/// </summary>
public sealed class LipGusset : IImplicit
{
    readonly float m_fXWeb, m_fXTip;    // web face and lip tip along x (mm)
    readonly float m_fZUnder;           // lip underside height (mm)
    readonly float m_fYHalf;            // half length along y (mm)
    readonly float m_fSin, m_fCos;      // underside slope from the plate
    readonly float m_fEmbed;            // overlap into web and lip (mm)

    public LipGusset(float fXWeb, float fXTip, float fZUnder, float fYHalf, float fSlopeDeg, float fEmbedMM)
    {
        if (fXTip <= fXWeb || fYHalf <= 0 || fSlopeDeg <= 0 || fSlopeDeg >= 90 || fEmbedMM < 0)
            throw new ArgumentException("Invalid gusset parameters");
        m_fXWeb = fXWeb; m_fXTip = fXTip; m_fZUnder = fZUnder; m_fYHalf = fYHalf; m_fEmbed = fEmbedMM;
        m_fSin = MathF.Sin(fSlopeDeg * MathF.PI / 180f);
        m_fCos = MathF.Cos(fSlopeDeg * MathF.PI / 180f);
    }

    /// <summary>Height at which the underside meets the web face (mm).</summary>
    public float fZAtWeb => m_fZUnder - (m_fXTip - m_fXWeb) * m_fSin / m_fCos;

    // Thread-safe: only reads fields.
    public float fSignedDistance(in Vector3 vec)
    {
        float fBack = (m_fXWeb - m_fEmbed) - vec.X;        // into the web
        float fTop = vec.Z - (m_fZUnder + m_fEmbed);        // into the lip
        float fTip = vec.X - m_fXTip;                       // flush with the lip end
        float fEnds = MathF.Abs(vec.Y) - m_fYHalf;          // flush with web and lip ends
        // Underside plane through the lip tip, outward normal (sin, 0, -cos).
        float fUnder = (vec.X - m_fXTip) * m_fSin + (m_fZUnder - vec.Z) * m_fCos;
        return MathF.Max(MathF.Max(MathF.Max(fBack, fTop), MathF.Max(fTip, fEnds)), fUnder);
    }
}

/// <summary>Axis-aligned box with exact signed distance.</summary>
public sealed class BoxImplicit : IImplicit
{
    readonly Vector3 m_vecCentre, m_vecHalf;

    public BoxImplicit(Vector3 vecMin, Vector3 vecMax)
    {
        m_vecCentre = 0.5f * (vecMin + vecMax);
        m_vecHalf = 0.5f * (vecMax - vecMin);
    }

    public float fSignedDistance(in Vector3 vec)
    {
        Vector3 q = Vector3.Abs(vec - m_vecCentre) - m_vecHalf;
        return Vector3.Max(q, Vector3.Zero).Length() + MathF.Min(MathF.Max(q.X, MathF.Max(q.Y, q.Z)), 0f);
    }
}

public static class LipGussetAndRib
{
    // Stated layout, millimetres. +z is the build direction.
    const float fXWeb = -18f, fXTip = -6f;          // web face and lip tip
    const float fZUnder = 35f;                      // lip underside
    const float fYHalf = 18f;                       // web and lip run over y = -18 .. 18
    const float fRibX = 5.4f;                       // rib mid-plane (faces at 5.0 and 5.8)
    const float fRibY0 = -18f, fRibY1 = -5f;        // rib extent along y
    const float fRibZ0 = 8f, fRibZ1 = 20f;          // rib from the plate top to its crest
    // Process assumptions, to be confirmed with coupons on the target machine.
    const float fOverhangDeg = 45f;                 // steepest unsupported downskin
    const float fSlopeDeg = 50f;                    // gusset underside, 5 deg margin
    const float fMinWallMM = 1.0f;                  // minimum printable wall
    const float fRibMM = 1.2f;                      // new rib thickness

    public static void Main(string[] args)
    {
        // Usage: LipGussetAndRib <bracket.stl> <output folder>
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    // Signed distance of the voxel field at a point: negative inside.
    static float fProbe(ScalarField sf, float fX, float fY, float fZ)
    {
        sf.bGetValue(new Vector3(fX, fY, fZ), out float fValue);   // also valid outside the narrow band
        return fValue;
    }

    /// <summary>
    /// Downward-facing area within 45 deg of straight down, as a slicer would
    /// flag it, inside a zone, skipping the band that rests on the plate.
    /// </summary>
    static float fOverhangArea(Mesh msh, BBox3 oZone, float fPlateZ)
    {
        float fCos = MathF.Cos(fOverhangDeg * MathF.PI / 180f), fArea = 0;
        for (int i = 0; i < msh.nTriangleCount(); i++)
        {
            msh.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
            Vector3 vecCross = Vector3.Cross(b - a, c - a);
            float fTwice = vecCross.Length();
            Vector3 vecCentre = (a + b + c) / 3f;
            if (fTwice > 0 && vecCross.Z / fTwice < -fCos && vecCentre.Z > fPlateZ && oZone.bContains(vecCentre))
                fArea += 0.5f * fTwice;
        }
        return fArea;
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        // Refuse settings the process assumptions cannot print or resolve.
        if (fSlopeDeg <= fOverhangDeg)
            throw new ArgumentException($"Gusset slope {fSlopeDeg} deg is not steeper than the {fOverhangDeg} deg limit");
        if (fRibMM < fMinWallMM || lib.fVoxelSize > fMinWallMM / 3f)
            throw new ArgumentException("Rib thinner than the minimum wall, or voxels too coarse to resolve it");

        // 1. Load and voxelise the closed, millimetre-scaled mesh.
        using Mesh mshIn = Mesh.mshFromStlFile(strInputPath, Mesh.EStlUnit.MM, libSet: lib);
        using Voxels voxBody = new(mshIn);
        if (voxBody.bIsEmpty()) throw new InvalidDataException("The mesh produced no volume; is it closed?");
        BBox3 oBox = voxBody.oCalculateBoundingBox();

        // 2. Check the stated layout before changing anything: lip material
        //    above its underside and air below it, web material and air beside
        //    it, rib material at its mid-plane and air 0.6 mm beyond each face.
        //    Probes stay at least 0.6 mm from any stated surface.
        using ScalarField sfBody = new(voxBody);
        float fLipX = 0.5f * (fXWeb + fXTip), fRibY = 0.5f * (fRibY0 + fRibY1), fRibZ = 0.5f * (fRibZ0 + fRibZ1);
        bool bLayout = fProbe(sfBody, fLipX, 0, fZUnder + 1.5f) < 0 && fProbe(sfBody, fLipX, 0, fZUnder - 1f) > 0 &&
                       fProbe(sfBody, fXWeb - 1f, 0, fZUnder - 6f) < 0 && fProbe(sfBody, fXWeb + 1.5f, 0, fZUnder - 6f) > 0 &&
                       fProbe(sfBody, fRibX, fRibY, fRibZ) < 0 &&
                       fProbe(sfBody, fRibX - 1f, fRibY, fRibZ) > 0 && fProbe(sfBody, fRibX + 1f, fRibY, fRibZ) > 0;
        if (!bLayout) throw new InvalidDataException("The part does not match the stated lip, web and rib layout");

        // 3. Gusset: fills the space under the lip down to a 50 deg underside,
        //    embedded 0.5 mm into web and lip so the union has no seam.
        LipGusset xGusset = new(fXWeb, fXTip, fZUnder, fYHalf, fSlopeDeg, 0.5f);
        if (xGusset.fZAtWeb <= oBox.vecMin.Z) throw new InvalidDataException("The gusset would reach below the part");
        BBox3 oGussetBox = new(new Vector3(fXWeb - 1f, -fYHalf - 1f, xGusset.fZAtWeb - 1f),
                               new Vector3(fXTip + 1f, fYHalf + 1f, fZUnder + 1f));
        using Voxels voxGusset = new(lib, xGusset, oGussetBox);

        // 4. Rib: a box symmetric about the rib mid-plane, from the plate top
        //    (0.5 mm into it) to the rib crest, over the rib's own length.
        BoxImplicit xRib = new(new Vector3(fRibX - 0.5f * fRibMM, fRibY0, fRibZ0 - 0.5f),
                               new Vector3(fRibX + 0.5f * fRibMM, fRibY1, fRibZ1));
        BBox3 oRibBox = new(new Vector3(fRibX - 2f, fRibY0 - 1f, fRibZ0 - 1.5f), new Vector3(fRibX + 2f, fRibY1 + 1f, fRibZ1 + 1f));
        using Voxels voxRib = new(lib, xRib, oRibBox);

        // 5. Union. voxBoolAdd returns a new object and leaves the body intact.
        using Voxels voxPart = voxBody.voxBoolAdd(voxGusset);
        voxPart.BoolAdd(voxRib);

        // 6. Wall check: an inward offset by half the minimum wall removes any
        //    wall thinner than the minimum. The rib must survive it.
        using Voxels voxCore = voxPart.voxOffset(-0.5f * fMinWallMM);
        using ScalarField sfCore = new(voxCore);
        if (fProbe(sfCore, fRibX, fRibY, fRibZ) >= 0)
            throw new InvalidDataException($"The rib is still thinner than {fMinWallMM} mm");

        // 7. Export. Weld vertices onto the checker's 0.0001 mm cell grid and
        //    drop faces that collapse, so the STL has no degenerate triangles.
        Directory.CreateDirectory(strOutputDir);
        using Mesh mshOut = voxPart.mshAsMesh();
        var triangles = new List<(Vector3 A, Vector3 B, Vector3 C)>();
        for (int i = 0; i < mshOut.nTriangleCount(); i++)
        {
            mshOut.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
            triangles.Add((a, b, c));
        }
        var clean = MeshCleanup.WeldAndFilter(triangles, 0.0001f, out int nRemoved, out float fMoved);
        if (clean.Count == 0) throw new InvalidDataException("Export cleanup produced an empty mesh");
        using Mesh mshClean = new(lib);
        foreach (var t in clean) mshClean.nAddTriangle(t.A, t.B, t.C);
        mshClean.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);

        // 8. Overhang under the lip, before and after, measured on the meshes.
        //    The gusset underside is 50 deg from the plate, so it is not counted.
        BBox3 oLipZone = new(new Vector3(fXWeb - 0.5f, -fYHalf - 0.5f, xGusset.fZAtWeb - 0.5f),
                             new Vector3(fXTip + 0.5f, fYHalf + 0.5f, fZUnder + 0.5f));
        float fPlateZ = oBox.vecMin.Z + 0.5f;
        float fBefore = fOverhangArea(mshIn, oLipZone, fPlateZ), fAfter = fOverhangArea(mshClean, oLipZone, fPlateZ);
        if (fAfter > 0.05f * fBefore)
            throw new InvalidDataException($"Overhang under the lip only fell from {fBefore:F0} to {fAfter:F0} mm2");
        voxBody.CalculateProperties(out float fBodyMM3, out _);
        voxPart.CalculateProperties(out float fPartMM3, out _);
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Lip overhang {0:F0} -> {1:F0} mm2; gusset meets the web at z = {2:F1} mm; added {3:F0} mm3 ({4:P1})",
            fBefore, fAfter, xGusset.fZAtWeb, fPartMM3 - fBodyMM3, (fPartMM3 - fBodyMM3) / fBodyMM3));
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Export cleanup removed {0} faces; maximum vertex displacement {1:G9} mm", nRemoved, fMoved));
    }
}

// Numerical export cleanup, independent of PicoGK and physical qualification.
// The corpus embeds this exact source so its C# example stays self-contained.
public static class MeshCleanup
{
    // Weld onto the first vertex in each quantized cell, preserving winding.
    // Vertices are actually replaced; merely dropping tiny faces could leave holes.
    public static List<(Vector3 A, Vector3 B, Vector3 C)> WeldAndFilter(
        IEnumerable<(Vector3 A, Vector3 B, Vector3 C)> input, float tolerance,
        out int removed, out float maxDisplacement)
    {
        if (!float.IsFinite(tolerance) || tolerance <= 0 || !float.IsFinite(1f / tolerance) ||
            !float.IsFinite(MathF.Sqrt(3) * tolerance))
            throw new ArgumentOutOfRangeException(nameof(tolerance));
        float scale = 1f / tolerance;
        var vertices = new Dictionary<(long, long, long), Vector3>();
        var result = new List<(Vector3, Vector3, Vector3)>();
        int dropped = 0;
        float moved = 0;

        Vector3 Weld(Vector3 v)
        {
            if (!float.IsFinite(v.X) || !float.IsFinite(v.Y) || !float.IsFinite(v.Z))
                throw new ArgumentException("Nonfinite mesh vertex");
            // Same rounded-cell convention as the independent STL checker.
            var key = (checked((long)MathF.Round(v.X * scale)),
                       checked((long)MathF.Round(v.Y * scale)),
                       checked((long)MathF.Round(v.Z * scale)));
            if (!vertices.TryGetValue(key, out Vector3 canonical))
            {
                // A vertex within the tolerance can sit just across a cell
                // boundary; left apart, the pair forms needle triangles.
                canonical = v;
                for (long dx = -1; dx <= 1 && canonical == v; dx++)
                    for (long dy = -1; dy <= 1 && canonical == v; dy++)
                        for (long dz = -1; dz <= 1 && canonical == v; dz++)
                            if (vertices.TryGetValue((key.Item1 + dx, key.Item2 + dy, key.Item3 + dz), out Vector3 near) &&
                                Vector3.Distance(near, v) <= tolerance)
                                canonical = near;
                // Only an unshared vertex claims the cell, so later vertices
                // never snap further than the cell-diagonal budget.
                if (canonical == v) vertices[key] = v;
            }
            float displacement = Vector3.Distance(v, canonical);
            // Large coordinates can lose precision during float quantization.
            // Refuse a weld that exceeds the cell-diagonal movement budget.
            if (!float.IsFinite(displacement) || displacement > MathF.Sqrt(3) * tolerance)
                throw new ArgumentException("Vertex weld exceeds the declared tolerance budget");
            moved = MathF.Max(moved, displacement);
            return canonical;
        }

        foreach (var t in input)
        {
            Vector3 a = Weld(t.A), b = Weld(t.B), c = Weld(t.C);
            Vector3 cross = Vector3.Cross(b - a, c - a);
            if (!float.IsFinite(cross.X) || !float.IsFinite(cross.Y) || !float.IsFinite(cross.Z))
                throw new ArgumentException("Nonfinite triangle area");
            // Remove collapsed and numerically zero-area faces after welding.
            if (a == b || b == c || a == c || cross.LengthSquared() == 0)
            {
                dropped++;
                continue;
            }
            result.Add((a, b, c));
        }
        removed = dropped;
        maxDisplacement = moved;
        return result;
    }
}

// Diamond (Schwarz D) sheet lattice inside a manifold block for PBF-LB/M,
// with a solid sleeve around every internal channel.
// Pipeline: closed STL -> voxels -> find the channels by morphological
// closing -> skin + sleeves -> D-sheet core -> powder openings -> STL.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Numerics;
using PicoGK;

/// <summary>
/// Sheet network of the Schwarz D (diamond) surface, from its nodal
/// approximation
///   sin x sin y sin z + sin x cos y cos z + cos x sin y cos z + cos x cos y sin z = 0
/// (von Schnering & Nesper (1991)). Dividing by the gradient turns the
/// level-set value into an approximate distance in millimetres, so the
/// thickness parameter is a wall thickness near the mid-surface.
/// </summary>
public sealed class DiamondSheet : IImplicit
{
    readonly float m_fK;          // 2 pi / cell size (rad/mm)
    readonly float m_fHalfWall;   // half the sheet thickness (mm)

    public DiamondSheet(float fCellMM, float fWallMM)
    {
        if (fCellMM <= 0 || fWallMM <= 0 || fWallMM >= 0.5f * fCellMM)
            throw new ArgumentException("Invalid cell size or wall thickness");
        m_fK = 2f * MathF.PI / fCellMM;
        m_fHalfWall = 0.5f * fWallMM;
    }

    // Thread-safe: only reads fields.
    public float fSignedDistance(in Vector3 vec)
    {
        var (sx, cx) = MathF.SinCos(m_fK * vec.X);
        var (sy, cy) = MathF.SinCos(m_fK * vec.Y);
        var (sz, cz) = MathF.SinCos(m_fK * vec.Z);
        float fF = sx * sy * sz + sx * cy * cz + cx * sy * cz + cx * cy * sz;
        // Partial derivatives in scaled coordinates.
        float fDx = cx * sy * sz + cx * cy * cz - sx * sy * cz - sx * cy * sz;
        float fDy = sx * cy * sz - sx * sy * cz + cx * cy * cz - cx * sy * sz;
        float fDz = sx * sy * cz - sx * cy * sz - cx * sy * sz + cx * cy * cz;
        float fGrad = m_fK * MathF.Sqrt(fDx * fDx + fDy * fDy + fDz * fDz);
        // Near critical points the gradient vanishes; there only the sign matters.
        float fDist = fF / MathF.Max(fGrad, 0.25f * m_fK);
        return MathF.Abs(fDist) - m_fHalfWall;
    }
}

public static class SleevedDiamondInfill
{
    // Design parameters, millimetres. All walls are process assumptions.
    const float fSkinMM = 1.5f;        // outer skin
    const float fSleeveMM = 2.0f;      // solid wall around every channel
    const float fCellMM = 12f;         // D-surface cubic cell
    const float fWallMM = 1.2f;        // lattice sheet thickness
    const float fMinWallMM = 1.0f;     // minimum printable wall
    const float fCloseMM = 5f;         // closes channels up to 10 mm across
    const float fOpeningMM = 4f;       // powder opening diameter

    public static void Main(string[] args)
    {
        // Usage: SleevedDiamondInfill <manifold.stl> <output folder>
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        if (Math.Min(fSkinMM, Math.Min(fSleeveMM, fWallMM)) < fMinWallMM || lib.fVoxelSize > fMinWallMM / 3f)
            throw new ArgumentException("A wall is below the minimum, or the voxels cannot resolve it");

        // 1. Load and voxelise the closed, millimetre-scaled mesh.
        using Mesh mshIn = Mesh.mshFromStlFile(strInputPath, Mesh.EStlUnit.MM, libSet: lib);
        using Voxels voxBody = new(mshIn);
        if (voxBody.bIsEmpty()) throw new InvalidDataException("The mesh produced no volume; is it closed?");
        BBox3 oBox = voxBody.oCalculateBoundingBox();

        // 2. Channels without hard-coding their path. A morphological closing
        //    (dilate, then erode by the same distance) fills every passage
        //    narrower than twice the distance and leaves the convex outside
        //    unchanged. What the closing added is the channel network, plus a
        //    shallow cap at each port. On the voxel grid the outside comes
        //    back only to within a fraction of a voxel, so an opening (erode,
        //    then dilate) removes that sliver before it is taken for a channel.
        using Voxels voxFilled = voxBody.voxOffset(fCloseMM);
        voxFilled.Offset(-fCloseMM);
        using Voxels voxChannels = voxFilled.voxBoolSubtract(voxBody);
        voxChannels.Offset(-0.5f);
        voxChannels.Offset(0.5f);
        voxChannels.CalculateProperties(out float fChannelMM3, out _);
        if (fChannelMM3 < 1f) throw new InvalidDataException("No internal channel found; nothing to protect");

        // 3. Core = the filled block shrunk by the skin, minus the channels
        //    grown by the sleeve. Skin and sleeves stay solid, so the fluid
        //    path is sealed from the lattice by at least the sleeve wall.
        using Voxels voxCore = voxFilled.voxOffset(-fSkinMM);
        using Voxels voxSleeved = voxChannels.voxOffset(fSleeveMM);
        voxCore.BoolSubtract(voxSleeved);
        if (voxCore.bIsEmpty()) throw new InvalidDataException("No room for a lattice inside skin and sleeves");

        // 4. D-sheet lattice clipped to the core; the part keeps everything
        //    outside the core. A TPMS is unbounded: render it in the part box.
        DiamondSheet xSheet = new(fCellMM, fWallMM);
        using Voxels voxSheet = new(lib, xSheet, oBox);
        using Voxels voxLattice = voxCore.voxBoolIntersect(voxSheet);
        using Voxels voxPart = voxBody.voxBoolSubtract(voxCore);
        voxPart.BoolAdd(voxLattice);

        // 5. Powder openings. The sheet splits the core into two labyrinths,
        //    both sealed by skin and sleeves. Vertical openings through the
        //    top, the last face built, reach down 0.75 cell into the core and
        //    so cut into both. An opening is kept only if it hits the core and
        //    stays a full minimum wall away from every channel.
        using Voxels voxGuard = voxChannels.voxOffset(fMinWallMM);
        Lattice latOpenings = new(lib);
        int nOpenings = 0;
        float fTop = oBox.vecMax.Z, fBottom = oBox.vecMax.Z - fSkinMM - 0.75f * fCellMM;
        for (float fX = oBox.vecMin.X + fCellMM; fX <= oBox.vecMax.X - fCellMM + 0.01f; fX += fCellMM)
        {
            for (float fY = oBox.vecMin.Y + 0.75f * fCellMM; fY <= oBox.vecMax.Y - 0.75f * fCellMM + 0.01f; fY += 1.5f * fCellMM)
            {
                Lattice latOne = new(lib);
                latOne.AddBeam(new Vector3(fX, fY, fTop + 1f), new Vector3(fX, fY, fBottom), 0.5f * fOpeningMM, 0.5f * fOpeningMM, false);
                using Voxels voxOne = new(latOne);
                using Voxels voxHitsCore = voxOne.voxBoolIntersect(voxCore);
                using Voxels voxHitsGuard = voxOne.voxBoolIntersect(voxGuard);
                if (voxHitsCore.bIsEmpty() || !voxHitsGuard.bIsEmpty()) continue;
                latOpenings.AddBeam(new Vector3(fX, fY, fTop + 1f), new Vector3(fX, fY, fBottom), 0.5f * fOpeningMM, 0.5f * fOpeningMM, false);
                nOpenings++;
            }
        }
        // Two openings at least, so powder can leave while air enters.
        if (nOpenings < 2) throw new InvalidDataException("Fewer than two powder openings fit clear of the channels");
        using Voxels voxOpenings = new(latOpenings);
        voxPart.BoolSubtract(voxOpenings);

        // 6. Trapped powder. Where skin and sleeves cut a piece of labyrinth off
        //    from the rest, no opening reaches it. Voxelising a mesh fills
        //    every region not connected to the outside, so the part voxelised
        //    from its own mesh has exactly those pockets filled. Small pockets
        //    are cheaper to make solid than to drain; a large total means the
        //    openings are in the wrong place.
        using Mesh mshOpen = voxPart.mshAsMesh();
        using Voxels voxFinal = new(mshOpen);
        voxPart.CalculateProperties(out float fOpenMM3, out _);
        voxFinal.CalculateProperties(out float fPartMM3, out _);
        float fPocketsMM3 = fPartMM3 - fOpenMM3;
        if (fPocketsMM3 > 0.02f * fPartMM3)
            throw new InvalidDataException($"{fPocketsMM3:F0} mm3 of lattice is sealed off; move or add openings");
        using Mesh mshPart = voxFinal.mshAsMesh();

        // 7. Export. Weld vertices onto the checker's 0.0001 mm cell grid and
        //    drop faces that collapse, so the STL has no degenerate triangles.
        Directory.CreateDirectory(strOutputDir);
        var triangles = new List<(Vector3 A, Vector3 B, Vector3 C)>();
        for (int i = 0; i < mshPart.nTriangleCount(); i++)
        {
            mshPart.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
            triangles.Add((a, b, c));
        }
        var clean = MeshCleanup.WeldAndFilter(triangles, 0.0001f, out int nRemoved, out float fMoved);
        if (clean.Count == 0) throw new InvalidDataException("Export cleanup produced an empty mesh");
        using Mesh mshClean = new(lib);
        foreach (var t in clean) mshClean.nAddTriangle(t.A, t.B, t.C);
        mshClean.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);

        voxBody.CalculateProperties(out float fBodyMM3, out _);
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Channels {0:F0} mm3, {1} openings, sealed pockets filled {2:F0} mm3, relative volume {3:F3}",
            fChannelMM3, nOpenings, fPocketsMM3, fPartMM3 / fBodyMM3));
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Export cleanup removed {0} faces; maximum vertex displacement {1:G9} mm", nRemoved, fMoved));
    }
}

