// Lightening pockets for PBF-LB/M that powder can leave: vertical pockets
// open through the bottom face, with self-supporting pointed tops.
// Pipeline: closed STL -> voxels -> per-pocket wall check -> cut -> sealed-
// cavity self-check -> STL.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Numerics;
using PicoGK;

public static class OpenLighteningPockets
{
    // Pocket layout and process assumptions, millimetres and degrees.
    const float fRadiusMM = 4f;        // 8 mm pockets
    const float fPlateMM = 16f;        // base plate thickness, as stated
    const float fRoofDeg = 50f;        // pointed top, 5 deg steeper than the limit
    const float fOverhangDeg = 45f;    // steepest unsupported downskin
    const float fWallMM = 2f;          // material kept around every pocket
    static readonly float[] afX = { -10f, 2f }, afY = { -12f, 0f, 12f };

    public static void Main(string[] args)
    {
        // Usage: OpenLighteningPockets <blank.stl> <output folder>
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        if (fRoofDeg <= fOverhangDeg)
            throw new ArgumentException($"A {fRoofDeg} deg roof is not steeper than the {fOverhangDeg} deg limit");

        // 1. Load and voxelise the closed, millimetre-scaled blank.
        using Mesh msh = Mesh.mshFromStlFile(strInputPath, Mesh.EStlUnit.MM, libSet: lib);
        using Voxels voxBody = new(msh);
        if (voxBody.bIsEmpty()) throw new InvalidDataException("The mesh produced no volume; is it closed?");
        float fBottomZ = voxBody.oCalculateBoundingBox().vecMin.Z;   // the face on the build plate

        // 2. Each pocket starts 1 mm below the bottom face, so it is open to
        //    the plate side and empties once the part is cut off the plate. A
        //    point whose flanks rise at 50 deg from the plate replaces the
        //    118 deg drill point, whose flanks sit only 31 deg from it. The
        //    steeper point is taller, so the straight bore ends lower to keep
        //    the wall under the top of the base plate.
        float fPointMM = fRadiusMM * MathF.Tan(fRoofDeg * MathF.PI / 180f);
        float fTopZ = fBottomZ + fPlateMM - fWallMM - fPointMM;
        Lattice latPockets = new(lib);
        int nPockets = 0;
        foreach (float fX in afX)
            foreach (float fY in afY)
            {
                Vector3 vecLow = new(fX, fY, fBottomZ - 1f), vecTop = new(fX, fY, fTopZ);
                Vector3 vecApex = new(fX, fY, fTopZ + fPointMM);

                // Wall check: grow this pocket by the wall and remove the body.
                // Whatever is left lies outside the part. Only the open bottom
                // may stick out; anything higher means a wall below 2 mm.
                Lattice latOne = new(lib);
                latOne.AddBeam(vecLow, vecTop, fRadiusMM, fRadiusMM, false);
                latOne.AddBeam(vecTop, vecApex, fRadiusMM, 0.05f, false);   // cone: radius tapers to a point
                using Voxels voxOne = new(latOne);
                using Voxels voxGrown = voxOne.voxOffset(fWallMM);
                using Voxels voxOutside = voxGrown.voxBoolSubtract(voxBody);
                if (!voxOutside.bIsEmpty() && voxOutside.oCalculateBoundingBox().vecMax.Z > fBottomZ + 0.5f)
                {
                    Console.WriteLine($"Skipped the pocket at x = {fX}, y = {fY}: less than {fWallMM} mm of wall");
                    continue;
                }
                latPockets.AddBeam(vecLow, vecTop, fRadiusMM, fRadiusMM, false);
                latPockets.AddBeam(vecTop, vecApex, fRadiusMM, 0.05f, false);
                nPockets++;
            }
        // Refuse rather than export an unchanged blank.
        if (nPockets == 0) throw new InvalidDataException("No pocket fits with the required wall");
        using Voxels voxPockets = new(latPockets);
        using Voxels voxPart = voxBody.voxBoolSubtract(voxPockets);   // returns a new object

        // 3. Sealed-cavity self-check. Voxelising a mesh fills every region
        //    that is not connected to the outside, so the volume it adds is
        //    cavity that powder cannot leave. Even without cavities the two
        //    volumes differ by a few mm3 of discretisation, so the limit is
        //    0.1 % of the part; one sealed pocket here is over 400 mm3.
        using Mesh mshPart = voxPart.mshAsMesh();
        using Voxels voxFilled = new(mshPart);
        voxPart.CalculateProperties(out float fPartMM3, out _);
        voxFilled.CalculateProperties(out float fFilledMM3, out _);
        float fLimitMM3 = 0.001f * fPartMM3;
        if (fFilledMM3 - fPartMM3 > fLimitMM3)
            throw new InvalidDataException($"{fFilledMM3 - fPartMM3:F0} mm3 of sealed cavity would trap powder");

        // 4. Export. Weld vertices onto the checker's 0.0001 mm cell grid and
        //    drop faces that collapse, so the STL has no degenerate triangles.
        Directory.CreateDirectory(strOutputDir);
        var triangles = new List<(Vector3 A, Vector3 B, Vector3 C)>();
        for (int i = 0; i < mshPart.nTriangleCount(); i++)
        {
            mshPart.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
            triangles.Add((a, b, c));
        }
        var clean = MeshCleanup.WeldAndFilter(triangles, 0.0001f, out int nRemoved, out float fMoved);
        if (clean.Count == 0) throw new InvalidDataException("Export cleanup produced an empty mesh");
        using Mesh mshClean = new(lib);
        foreach (var t in clean) mshClean.nAddTriangle(t.A, t.B, t.C);
        mshClean.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);

        voxBody.CalculateProperties(out float fBodyMM3, out _);
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "{0} pockets, removed {1:F0} mm3 ({2:P1}); cavity check {3:F1} mm3 (limit {4:F0})",
            nPockets, fBodyMM3 - fPartMM3, (fBodyMM3 - fPartMM3) / fBodyMM3, fFilledMM3 - fPartMM3, fLimitMM3));
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Export cleanup removed {0} faces; maximum vertex displacement {1:G9} mm", nRemoved, fMoved));
    }
}

// Numerical export cleanup, independent of PicoGK and physical qualification.
// The corpus embeds this exact source so its C# example stays self-contained.
public static class MeshCleanup
{
    // Weld onto the first vertex in each quantized cell, preserving winding.
    // Vertices are actually replaced; merely dropping tiny faces could leave holes.
    public static List<(Vector3 A, Vector3 B, Vector3 C)> WeldAndFilter(
        IEnumerable<(Vector3 A, Vector3 B, Vector3 C)> input, float tolerance,
        out int removed, out float maxDisplacement)
    {
        if (!float.IsFinite(tolerance) || tolerance <= 0 || !float.IsFinite(1f / tolerance) ||
            !float.IsFinite(MathF.Sqrt(3) * tolerance))
            throw new ArgumentOutOfRangeException(nameof(tolerance));
        float scale = 1f / tolerance;
        var vertices = new Dictionary<(long, long, long), Vector3>();
        var result = new List<(Vector3, Vector3, Vector3)>();
        int dropped = 0;
        float moved = 0;

        Vector3 Weld(Vector3 v)
        {
            if (!float.IsFinite(v.X) || !float.IsFinite(v.Y) || !float.IsFinite(v.Z))
                throw new ArgumentException("Nonfinite mesh vertex");
            // Same rounded-cell convention as the independent STL checker.
            var key = (checked((long)MathF.Round(v.X * scale)),
                       checked((long)MathF.Round(v.Y * scale)),
                       checked((long)MathF.Round(v.Z * scale)));
            if (!vertices.TryGetValue(key, out Vector3 canonical))
            {
                // A vertex within the tolerance can sit just across a cell
                // boundary; left apart, the pair forms needle triangles.
                canonical = v;
                for (long dx = -1; dx <= 1 && canonical == v; dx++)
                    for (long dy = -1; dy <= 1 && canonical == v; dy++)
                        for (long dz = -1; dz <= 1 && canonical == v; dz++)
                            if (vertices.TryGetValue((key.Item1 + dx, key.Item2 + dy, key.Item3 + dz), out Vector3 near) &&
                                Vector3.Distance(near, v) <= tolerance)
                                canonical = near;
                // Only an unshared vertex claims the cell, so later vertices
                // never snap further than the cell-diagonal budget.
                if (canonical == v) vertices[key] = v;
            }
            float displacement = Vector3.Distance(v, canonical);
            // Large coordinates can lose precision during float quantization.
            // Refuse a weld that exceeds the cell-diagonal movement budget.
            if (!float.IsFinite(displacement) || displacement > MathF.Sqrt(3) * tolerance)
                throw new ArgumentException("Vertex weld exceeds the declared tolerance budget");
            moved = MathF.Max(moved, displacement);
            return canonical;
        }

        foreach (var t in input)
        {
            Vector3 a = Weld(t.A), b = Weld(t.B), c = Weld(t.C);
            Vector3 cross = Vector3.Cross(b - a, c - a);
            if (!float.IsFinite(cross.X) || !float.IsFinite(cross.Y) || !float.IsFinite(cross.Z))
                throw new ArgumentException("Nonfinite triangle area");
            // Remove collapsed and numerically zero-area faces after welding.
            if (a == b || b == c || a == c || cross.LengthSquared() == 0)
            {
                dropped++;
                continue;
            }
            result.Add((a, b, c));
        }
        removed = dropped;
        maxDisplacement = moved;
        return result;
    }
}

