using System;
using System.IO;
using System.Numerics;
using PicoGK;

public static class LighteningPockets
{
    public static void Main(string[] args)
    {
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        // Load the blank and voxelise it.
        using Mesh msh = Mesh.mshFromStlFile(strInputPath, Mesh.EStlUnit.MM, libSet: lib);
        using Voxels voxBody = new(msh);

        // 8 mm pockets from the 2 mm floor up to z = 10 mm, each topped
        // with a standard 118 degree drill point.
        const float fR = 4f, fFloor = 2f, fTop = 10f;
        float fPoint = fR / MathF.Tan(59f * MathF.PI / 180f);
        Lattice lat = new(lib);
        foreach (float fX in new[] { -10f, 2f })
            foreach (float fY in new[] { -12f, 0f, 12f })
            {
                lat.AddBeam(new Vector3(fX, fY, fFloor), new Vector3(fX, fY, fTop), fR, fR, false);
                lat.AddBeam(new Vector3(fX, fY, fTop), new Vector3(fX, fY, fTop + fPoint), fR, 0.05f, false);
            }
        using Voxels voxPockets = new(lat);
        using Voxels voxPart = voxBody.voxBoolSubtract(voxPockets);

        // Export.
        Directory.CreateDirectory(strOutputDir);
        using Mesh mshOut = voxPart.mshAsMesh();
        mshOut.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);
    }
}
